"""One-time authoring of the second-edition physical closure milestones."""
from common import ROOT, parse, write, dump
import json

def emit(path, meta, body):
    write(ROOT/path, '```json\n'+json.dumps(meta,indent=2,ensure_ascii=False)+'\n```\n\n'+body)

def main():
    path='curriculum/modules/T38.md'
    meta,body=parse(ROOT/path)
    if 'PR-T38-11' in meta['projects']: return
    meta['projects']+=['PR-T38-11','PR-T38-12']
    meta['workload']['implementation']+=12
    meta['workload']['verification']+=8
    meta['workload']['reading']+=2
    meta['readings'].append({'resource_id':'R-V2-COM-MCP2518FD-B','locator':'1.1–1.3, printed pages 3–5','purpose':'Separate controller, transceiver, supply and SPI/interrupt responsibilities before physical FD work','hours':2})
    meta['equipment']=[v.replace('optional separately powered external FD controller/peer','required separately powered external FD controller/peer') for v in meta['equipment']]
    body=body.replace('physical FD is an explicit optional additional closure, not a silently missing protocol topic.','physical FD is required in edition 2 through PR-T38-11 and PR-T38-12. Completion of metadata tests alone leaves the FD physical gate open.')
    body=body.replace('Optional external FD has separate power/driver/setup scope.','Required external FD has separately budgeted bring-up and physical exchange milestones.')
    body=body.replace('## Implementation projects','The physical FD continuation reuses T38.12 in {ref}`PR-T38-11` and {ref}`PR-T38-12`. Consult {ref}`guide-physical-evidence` for the completion contract.\n\n## Implementation projects')
    emit(path,meta,body)
    p='curriculum/projects/PR-T38-10.md'; m,b=parse(ROOT/p)
    b=b.replace('Optional physical closure requires','Required edition-2 physical closure in PR-T38-11 and PR-T38-12 requires').replace('close optional physical FD','close the required physical FD gate').replace('optional hardware mastery needs','full-program hardware mastery needs')
    emit(p,m,b)
    descriptions=[
      ('11','CAN FD controller bring-up and ownership boundary', '''Bring up an MCP2518FD external CAN FD controller connected to the existing Cortex-M4 route. Deliver a pin/power/clock ledger, bounded SPI transactions, error propagation and a captured controller identification/loopback transaction. Treat controller initialization and frame storage as a state machine with bounded waits. Keep the prior TCAN4550 synthetic fixture as a comparison; its command framing and supply limits do not describe this controller.''',
       ['Record exact board revisions, schematic, oscillator and controller/transceiver revisions. Inspect the exact controller SPI, reset, RAM initialization, FIFO and interrupt passages before assigning register values; record their locators in the dossier.', 'Reuse the inspected SPI primitive with explicit chip-select ownership and timeout/error returns. Separate transport errors, device status and CAN errors.', 'Initialize the selected FIFO/RAM arrangement and verify configuration/readback before entering loopback. Capture the actual SPI command and response bytes.', 'Inject a disconnected controller and a deliberately mismatched mode in the isolated setup. Show bounded failure, then restore the known configuration.'],
       'A register read returning all ones is not evidence of a valid device. No completion event before chip-select/transaction ownership is released. A valid internal loopback establishes controller-path behavior; it leaves the wire exchange for PR-T38-12.'),
      ('12','Physical CAN FD dual-rate exchange and recovery', '''Complete a physical CAN FD exchange between the Cortex-M4 external-controller route and an independent compatible FD peer. Reuse the validated controller boundary from PR-T38-11. Record nominal/data phase rates, transceiver topology, termination, clock assumptions and actual captures. Choose rates supported by every device and the measured wiring; a advertised maximum is not the lab configuration.''',
       ['Predict valid DLC/payload pairs using PR-T38-10. Send zero, eight, twelve and sixty-four-byte payloads with sequence and end-to-end check fields.', 'Capture both no-BRS and BRS-enabled traffic. Identify arbitration and data phases, acknowledgement, retransmission and the observation point of software timestamps.', 'Exercise missing peer acknowledgement, filter rejection and bounded software queue exhaustion. Record counters, timeout and recovery behavior without using successful metadata validation as a wire-level verdict.', 'Repeat with a changed data-phase rate and a fresh payload generated by the independent peer. Compare intended and observed values and account for capture resolution.'],
       'Reject missing ACK, wrong sequence or payload, unbounded retry and absent raw captures. Full closure needs peer receive evidence plus a physical capture and measured configuration; virtual CAN and internal loopback leave this claim not-run.')]
    for number,title,contract,steps,acceptance in descriptions:
        key='PR-T38-'+number
        meta={'id':key,'title':title,'module':'T38','topics':['T38.12'],'status':'core','hours':10,'profile':'E','fixtures':['fixtures/communications/PR-T38-10.json'],'edition':2,'evidence_template':'physical','requires_projects':['PR-T38-'+('10' if number=='11' else '11')]}
        body='## Contract\n\n'+contract+'\n\nThis milestone budgets six hours implementation and four hours verification. Equipment acquisition is an entry prerequisite. Readings are budgeted separately in T38.\n\n## Inputs and expected results\n\nReplay the prior metadata fixture with `python tools/verify_communications_fixtures.py`; its mathematical expectations establish only the shared software input contract. Actual electrical values and device responses must come from the recorded configuration and raw measurements. Use the inspected source scope R-V2-COM-MCP2518FD-B for the block/power boundary, then inspect exact implementation passages for the selected board.\n\n## Steps\n\n'+'\n'.join(str(i+1)+'. '+s for i,s in enumerate(steps))+'\n\n## Failure cases\n\nIncorrect supply/logic domains, stale interrupt status, impossible DLC/length, missing peer, wrong timing, buffer exhaustion and a timeout without a documented reset/recovery state. Explain which boundary detects each failure and preserves ownership.\n\n## Acceptance and evidence\n\n'+acceptance+' Follow {ref}`guide-physical-evidence`. Preserve source/build identity, setup photograph or schematic, instrument configuration, raw capture, interpretation and a changed-condition repeat. Automated family tests do not close this milestone.\n\n## Hints and recovery\n\nFirst validate the lowest failed boundary: power and clock, then SPI command/response, controller state, transceiver and peer. Save the first contradictory observation before changing configuration. A known-good peer helps localize a fault but does not replace the learner driver.\n\n## Transfer challenge\n\nExplain the evidence that would need to be repeated after changing the oscillator or transceiver. Repeat one relevant measurement with the changed condition and preserve the earlier result for comparison.\n'
        emit('curriculum/projects/'+key+'.md',meta,body)
    resource={'id':'R-V2-COM-MCP2518FD-B','title':'MCP2518FD External CAN FD Controller with SPI Interface','authors':['Microchip Technology Inc.'],'edition':'DS20006027B','year':2020,'kind':'manual','url':'https://ww1.microchip.com/downloads/aemDocuments/documents/OTH/ProductDocuments/DataSheets/External-CAN-FD-Controller-with-SPI-Interface-DS20006027B.pdf','access':'Public official datasheet','domains':['T38'],'role':'primary','reason':'Ground the external-controller physical boundary','prerequisites':['SPI transactions','Supply and logic domains'],'locators':['1.1–1.3, printed pages 3–5'],'assignable':True,'inspection':{'date':'2026-10-10','method':'Official PDF text inspection','scope':'Device overview, pinout and typical 3.3V application in sections 1.1–1.3 only. Controller VDD/logic and transceiver supply/logic are separate responsibilities.','limits':'Not a complete driver recipe. Exact register/FIFO/init passages and board schematic must be inspected before implementation.'}}
    dump(ROOT/'research/v2/physical_resources.json',[resource])

if __name__=='__main__': main()
